using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 Vector3 PursuitGround(float x,float z){var p=Ground(x,z);if(EncounterPursuitFloor(x,z,out float storyFloor)){p.Y=storyFloor;return p;}if(LetterNodeLive(checkpointRoot)){if(Math.Abs(x-CheckpointX)<3.5&&Math.Abs(z-ExpeditionCheckpoint.Z)<=20||x>CheckpointX+3.5&&x<CheckpointX+10.5&&z>ExpeditionCheckpoint.Z-16.5&&z<ExpeditionCheckpoint.Z-3.5){p.Y=(float)checkpointFloor;return p;}if(Math.Abs(x-CheckpointX)<1.5&&Math.Abs(z-ExpeditionCheckpoint.Z)>20&&Math.Abs(z-ExpeditionCheckpoint.Z)<=36){double end=z<ExpeditionCheckpoint.Z?ExpeditionCheckpoint.Z-36:ExpeditionCheckpoint.Z+36;p.Y=Mathf.Lerp((float)checkpointFloor,Ground(CheckpointX,end).Y,(float)((Math.Abs(z-ExpeditionCheckpoint.Z)-20)/16));return p;}}if(LetterNodeLive(birthdayHouse)){if(Math.Abs(x-BirthdayX)<3.9&&z>ExpeditionBirthday.Z-4.9&&z<ExpeditionBirthday.Z+6.3){p.Y=(float)birthdayFloor;return p;}if(Math.Abs(x-BirthdayX)<1.5&&z>=ExpeditionBirthday.Z+6.3&&z<=ExpeditionBirthday.Z+21){p.Y=Mathf.Lerp((float)birthdayFloor,Ground(BirthdayX,ExpeditionBirthday.Z+21).Y,(float)((z-ExpeditionBirthday.Z-6.3)/14.7));return p;}}if(LetterNodeLive(letterChurch)){if(Math.Abs(x-LetterChurchX)<5.9&&z>ExpeditionLastLetter.ChurchZ-11.9&&z<ExpeditionLastLetter.ChurchZ+12){p.Y=(float)letterChurchFloor;return p;}if(Math.Abs(x-LetterChurchX)<1.5&&z>=ExpeditionLastLetter.ChurchZ+12&&z<=ExpeditionLastLetter.ChurchZ+30){p.Y=Mathf.Lerp((float)letterChurchFloor,Ground(LetterChurchX,ExpeditionLastLetter.ChurchZ+30).Y,(float)((z-ExpeditionLastLetter.ChurchZ-12)/18));return p;}}if(LetterNodeLive(letterHome)){if(Math.Abs(x-LetterHomeX)<3.9&&z>ExpeditionLastLetter.HomeZ-4.9&&z<ExpeditionLastLetter.HomeZ+6.3){p.Y=(float)letterHomeFloor;return p;}if(Math.Abs(x-LetterHomeX)<1.5&&z>=ExpeditionLastLetter.HomeZ+6.3&&z<=ExpeditionLastLetter.HomeZ+21){p.Y=Mathf.Lerp((float)letterHomeFloor,Ground(LetterHomeX,ExpeditionLastLetter.HomeZ+21).Y,(float)((z-ExpeditionLastLetter.HomeZ-6.3)/14.7));return p;}}if(GodotObject.IsInstanceValid(feverHouse)&&feverHouse.IsInsideTree()){if(Math.Abs(x-FeverX)<3.9&&z>FeverZ-4.9&&z<FeverZ+7.3){p.Y=(float)feverFloor;return p;}if(Math.Abs(x-FeverX)<1.35&&z>=FeverZ+7.3&&z<=FeverZ+21){p.Y=Mathf.Lerp((float)feverFloor,Ground(FeverX,FeverZ+21).Y,(float)((z-FeverZ-7.3)/13.7));return p;}}if(!GodotObject.IsInstanceValid(millRoot)||!millRoot.IsInsideTree())return p;float mx=(float)(x-MillX),mz=(float)(z-MillZ);if(Math.Abs(mx)<25&&Math.Abs(mz)<25)p.Y=(float)millFloor;else if(Math.Abs(mx)<3&&mz>=24&&mz<=49){float end=Ground(MillX,MillZ+49).Y;p.Y=Mathf.Lerp((float)millFloor,end,(mz-24)/25);}return p;}
 void CatchUpCommunity(double dt){foreach(var n in Community.Survivors){if(n.State=="trapped"||n.Downed)continue;string owner=n.Member?n.Owner:n.EscortOwner;var leader=CommunityLeader(owner);bool observed=CoopHost?NearActiveSurface(NpcPoint(n),45):Distance(player.Position,NpcPoint(n))<45;if(observed){n.ReturnTime=0;continue;}Vector3 destination=NpcPoint(n);bool relocate=false;
   if(leader!=null&&Distance(leader.Value.Body.Position,NpcPoint(n))>80&&!infected.Any(e=>Distance(e.Body.Position,leader.Value.Body.Position)<20)){var point=leader.Value.Body.Position;destination=Ground(point.X+5,point.Z+5)+Vector3.Up*.5f;relocate=OutdoorFree(destination.X,destination.Z);}
   else if(n.Member&&string.IsNullOrEmpty(n.Owner)&&ExpeditionGame.Distance(n.X,n.Z,Community.X,Community.Z)>30){n.ReturnTime+=dt;if(n.ReturnTime>15){destination=Ground(Community.X+2.5,Community.Z+2.5)+Vector3.Up*1.2f;relocate=true;}}
   if(!relocate)continue;n.X=destination.X;n.Y=destination.Y;n.Z=destination.Z;n.ReturnTime=0;if(communityAvatars.TryGetValue(n.Id,out var a)){a.Mover.Body.Position=destination;a.Mover.Body.Velocity=Vector3.Zero;a.Mover.Path.Clear();}
  }}
}
